sys_script_include.script:
var CreateSamPropertyMismatchTask = Class.create();
CreateSamPropertyMismatchTask.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    initialize: function () {},

    processCreateTasks: function () {
        var propertyName = 'sam.properties'; 
        var propertyData = gs.getProperty(propertyName); 
        var results = [];

        if (!propertyData) {
            gs.error('System property "' + propertyName + '" is empty or not set.');
            return 'No tasks created. System property is missing.';
        }

        try {
            var properties = JSON.parse(propertyData);
            gs.info('Processing property: ' + propertyName + ', Parsed data: ' + JSON.stringify(properties));

            for (var i = 0; i < properties.length; i++) {
                var prop = properties[i];

                if (!this.validateProperty(prop)) {
                    gs.error('Invalid property structure: ' + JSON.stringify(prop));
                    continue;
                }

                // Get the actual value from sys_properties
                var actualValue = this.getSysPropertyValue(prop.property);

                if (actualValue === null) {
                    gs.error('Property not found in sys_properties: ' + prop.property);
                    continue;
                }

                gs.info('Current value for property ' + prop.property + ': ' + actualValue);

                // Check if the values differ (suggested vs actual)
                if (actualValue !== prop.suggested_value) {
                    if (this.taskExists(prop.property, actualValue, prop.suggested_value)) {
                        gs.info('Task already exists for property: ' + prop.property);
                        continue;
                    }

                    var taskId = this.createTask(prop, actualValue);
                    if (taskId) {
                        results.push('Task created for: ' + prop.property + ' (ID: ' + taskId + ')');
                    }
                }
            }
        } catch (e) {
            gs.error('Error processing JSON in "' + propertyName + '": ' + e.message);
        }

        return results.length > 0 ? results.join('\n') : 'No tasks were created.';
    },

    getSysPropertyValue: function (propertyName) {
        var gr = new GlideRecord('sys_properties');
        gr.addQuery('name', propertyName);
        gr.query();

        if (gr.next()) {
            return gr.getValue('value');
        }
        return null; // Property not found
    },

    validateProperty: function (prop) {
        if (!prop.name || !prop.property || !prop.suggested_value) {
            gs.error('Missing fields in property object: ' + JSON.stringify(prop));
            return false;
        }
        return true;
    },

    taskExists: function (property, currentValue, suggestedValue) {
        var gr = new GlideRecord('samp_sp_vb_task');
        gr.addQuery('description', property);
        gr.addQuery('current_value', currentValue);
        gr.addQuery('suggested_value', suggestedValue);
        gr.addEncodedQuery('stateNOT IN2,-5,3,7'); 
        gr.query();
        return gr.hasNext();
    },

    createTask: function (prop, currentValue) {
        var taskGr = new GlideRecord('samp_sp_vb_task');
        taskGr.initialize();
        taskGr.setValue('description', 'Mismatch in system property: ' + prop.name);
        taskGr.setValue('usecase', prop.property);
        taskGr.setValue('instructions', 'Current Value: ' + currentValue + ', Suggested Value: ' + prop.suggested_value);
        taskGr.setValue('current_value', currentValue);
        taskGr.setValue('suggested_value', prop.suggested_value);

        return taskGr.insert();
    },

    type: 'CreateSamPropertyMismatchTask'
});
